import{_ as e,o as a,c as d,a5 as o}from"./chunks/framework.DGp912Ge.js";const f=JSON.parse('{"title":"Gait & Status Reference","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/ros/reference.md","filePath":"software/sdk/ros/reference.md","lastUpdated":1785213527000}'),l={name:"software/sdk/ros/reference.md"};function s(i,t,n,r,c,g){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="gait-status-reference" tabindex="-1">Gait &amp; Status Reference <a class="header-anchor" href="#gait-status-reference" aria-label="Permalink to &quot;Gait &amp; Status Reference&quot;">​</a></h1><p>Complete reference for the gait IDs and the <code>rbq_msgs/RobotStatus</code> fields used across ROS 2 topics and SDK calls.</p><hr><h2 id="gait-state-ids" tabindex="-1">Gait State IDs <a class="header-anchor" href="#gait-state-ids" aria-label="Permalink to &quot;Gait State IDs&quot;">​</a></h2><p>Set via <code>/rbq/cmd/switch_gait</code> (Sub) or the <code>gait_state</code> field of <code>rbq_msgs/HighLevelCommand</code>; the current value is reported on <code>/rbq/robot_status</code> → <code>gait_id</code> (Pub). Commands and status share <strong>one</strong> gait enum — every id below means the same thing whether you send it on <code>HighLevelCommand.gait_state</code> or read it back from <code>robot_status.gait_id</code>.</p><h3 id="standard-gaits" tabindex="-1">Standard gaits <a class="header-anchor" href="#standard-gaits" aria-label="Permalink to &quot;Standard gaits&quot;">​</a></h3><p>Sent on <code>HighLevelCommand.gait_state</code> / <code>switch_gait</code>, and reported back unchanged on <code>robot_status.gait_id</code>.</p><table tabindex="0"><thead><tr><th style="text-align:center;">ID</th><th style="text-align:left;">Constant</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><code>-3</code></td><td style="text-align:left;">—</td><td style="text-align:left;">Fall Recovery — automatic recovery attempt after a fall</td></tr><tr><td style="text-align:center;"><code>-2</code></td><td style="text-align:left;"><code>STATE_FALL</code></td><td style="text-align:left;">Fall Mode — triggered upon unexpected loss of balance</td></tr><tr><td style="text-align:center;"><code>-1</code></td><td style="text-align:left;"><code>STATE_OFF</code></td><td style="text-align:left;">Control Off — all actuators disabled</td></tr><tr><td style="text-align:center;"><code>0</code></td><td style="text-align:left;"><code>STATE_SIT</code></td><td style="text-align:left;">Sitting — low posture, resting on the ground</td></tr><tr><td style="text-align:center;"><code>1</code></td><td style="text-align:left;"><code>STATE_STAND</code></td><td style="text-align:left;">Standing — neutral posture, ready to walk</td></tr><tr><td style="text-align:center;"><code>3</code></td><td style="text-align:left;"><code>STATE_WALK</code></td><td style="text-align:left;">Walk Mode — walking trot gait</td></tr><tr><td style="text-align:center;"><code>4</code></td><td style="text-align:left;"><code>STATE_STAIRS</code></td><td style="text-align:left;">Stairs Mode — stair-adaptive gait using the camera sensor</td></tr><tr><td style="text-align:center;"><code>5</code></td><td style="text-align:left;"><code>STATE_WAVE</code></td><td style="text-align:left;">Wave Mode — walking wave gait</td></tr><tr><td style="text-align:center;"><code>10</code></td><td style="text-align:left;">—</td><td style="text-align:left;">Docking — auto-docking sequence</td></tr></tbody></table><blockquote><p><code>-3</code> and <code>10</code> have no <code>STATE_*</code> constant in <code>HighLevelCommand.msg</code> — assign the number directly to <code>gait_state</code>.</p></blockquote><h3 id="rl-based-gaits" tabindex="-1">RL-based gaits <a class="header-anchor" href="#rl-based-gaits" aria-label="Permalink to &quot;RL-based gaits&quot;">​</a></h3><p>RL gaits use learned locomotion policies (ONNX inference via <code>RLWalk</code>).</p><table tabindex="0"><thead><tr><th style="text-align:center;">ID</th><th style="text-align:left;">Constant</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><code>48</code></td><td style="text-align:left;">—</td><td style="text-align:left;">RL Walk (Vision) — learned walking gait with vision-based terrain adaptation</td></tr><tr><td style="text-align:center;"><code>49</code></td><td style="text-align:left;">—</td><td style="text-align:left;">RL Walk — learned walking gait</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Setting an RL gait</p><p><code>HighLevelCommand.msg</code> does not yet define name constants for these ids — assign the number directly to <code>gait_state</code> (for example <code>gait_state: 49</code>). RL gaits also require a loaded policy file and the <code>RLWalk</code> process to be running. Not all ids are available on every robot configuration.</p></div><hr><h2 id="robot-status-fields-rbq-robot-status" tabindex="-1">Robot Status Fields (<code>/rbq/robot_status</code>) <a class="header-anchor" href="#robot-status-fields-rbq-robot-status" aria-label="Permalink to &quot;Robot Status Fields (`/rbq/robot_status`)&quot;">​</a></h2><p>Published as <code>rbq_msgs/RobotStatus</code> on <code>/rbq/robot_status</code> (Pub, ~500 Hz). Every entry below is a flat field of the message.</p><h3 id="state-flags-bool" tabindex="-1">State flags (<code>bool</code>) <a class="header-anchor" href="#state-flags-bool" aria-label="Permalink to &quot;State flags (`bool`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">ROS field</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>con_start</code></td><td style="text-align:left;">Motor control loop is running</td></tr><tr><td style="text-align:left;"><code>ready_pos</code></td><td style="text-align:left;">Robot reached ready position</td></tr><tr><td style="text-align:left;"><code>ground_pos</code></td><td style="text-align:left;">Robot is in ground/sit position</td></tr><tr><td style="text-align:left;"><code>force_con</code></td><td style="text-align:left;">Force control mode active</td></tr><tr><td style="text-align:left;"><code>ext_joy</code></td><td style="text-align:left;">External joystick input active</td></tr><tr><td style="text-align:left;"><code>is_standing</code></td><td style="text-align:left;">Robot is standing</td></tr><tr><td style="text-align:left;"><code>can_check</code></td><td style="text-align:left;">CAN communication verified with all joints</td></tr><tr><td style="text-align:left;"><code>find_home</code></td><td style="text-align:left;">Encoder homing complete on all joints</td></tr></tbody></table><h3 id="gait-docking" tabindex="-1">Gait &amp; docking <a class="header-anchor" href="#gait-docking" aria-label="Permalink to &quot;Gait &amp; docking&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">ROS field</th><th style="text-align:left;">Type</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>gait_id</code></td><td style="text-align:left;"><code>int8</code></td><td style="text-align:left;">Current active gait (see <a href="#gait-state-ids">Gait State IDs</a>)</td></tr><tr><td style="text-align:left;"><code>docking_state</code></td><td style="text-align:left;"><code>int8</code></td><td style="text-align:left;">Docking sequence state (see the docking-state table in the <a href="/RBQ/software/sdk/ros/topics.html#robot-status">Topic Reference</a>)</td></tr></tbody></table><h3 id="system-flags-bool" tabindex="-1">System flags (<code>bool</code>) <a class="header-anchor" href="#system-flags-bool" aria-label="Permalink to &quot;System flags (`bool`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">ROS field</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>is_fall</code></td><td style="text-align:left;">Robot has detected a fall</td></tr><tr><td style="text-align:left;"><code>imu_success</code></td><td style="text-align:left;">IMU connected and data valid</td></tr></tbody></table><hr><h2 id="typical-initialization-sequence" tabindex="-1">Typical initialization sequence <a class="header-anchor" href="#typical-initialization-sequence" aria-label="Permalink to &quot;Typical initialization sequence&quot;">​</a></h2><p>Monitor these flags after sending <code>/rbq/cmd/auto_start</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>can_check  → true   (CAN verified)</span></span>\n<span class="line"><span>find_home  → true   (encoders homed)</span></span>\n<span class="line"><span>con_start  → true   (control running)</span></span>\n<span class="line"><span>gait_id    → 0      (STATE_SIT, ready for commands)</span></span></code></pre></div><p>Once all three flags are <code>true</code>, the robot accepts gait and motion commands.</p>',27)])])}const b=e(l,[["render",s]]);export{f as __pageData,b as default};
